{
  "findings": [
    {
      "check_id": "CKV_AWS_104",
      "title": "Elasticsearch domain encryption at rest is disabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "HIGH",
      "explanation": "The 'encrypt_at_rest' block explicitly sets 'enabled = false', leaving sensitive log data stored on EBS volumes unencrypted. This violates security best practices and compliance requirements for data protection."
    }
  ],
  "patched_code": "resource "aws_elasticsearch_domain" "log_search_database" {
  domain_name           = "enterprise-log-analytics-es"
  elasticsearch_version = "7.10"
  cluster_config {
    instance_type  = var.elasticsearch_instance_type
    instance_count = 2
  }
  vpc_options {
    subnet_ids         = [aws_subnet.data_subnet_az1.id]
    security_group_ids = [aws_security_group.elasticsearch_sg.id]
  }
  ebs_options {
    ebs_enabled = true
    volume_size = 20
    volume_type = "gp2"
  }
  encrypt_at_rest {
    enabled = true
  }
}",
  "fix_summary": "Changed the 'enabled' attribute in the 'encrypt_at_rest' block from false to true to ensure that data stored in the Elasticsearch domain is encrypted at rest."
}
